// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(address attacker) public {
        vm.assume(attacker != address(0));
        vm.deal(address(c), 1 ether);

        vm.deal(attacker, 1 ether);

        vm.prank(attacker);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = c.smartfix_owner();

        assertTrue(attacker == owner || ok == false);
    }
}
